    for k in keys:
        root = insert(root, k)
    return root


def inorder(root):
    return [] if root is None else inorder(root.left) + [root.key] + inorder(root.right)


def delete(root, key):
    if root is None:
        return None
    if key < root.key:
        root.left = delete(root.left, key)
    elif key > root.key:
        root.right = delete(root.right, key)
    else:
        if root.left is None:          # zero or one child
            return root.right
        if root.right is None:
            return root.left
        succ = root.right              # two children: in-order successor
        while succ.left is not None:
            succ = succ.left
        root.key = succ.key
        root.right = delete(root.right, succ.key)
    return root


