COLORS = ["black", "brown", "red", "orange", "yellow",
          "green", "blue", "violet", "grey", "white"]


def color_bands(ohms):
    """4700 -> ['yellow', 'violet', 'red'] (two digits + multiplier)."""
    if ohms < 10 or ohms != int(ohms):
        raise ValueError("this version handles whole values from 10 Ω up")
    digits = str(int(ohms))
    first, rest = digits[:2], digits[2:]
    if rest.strip("0"):
        raise ValueError("needs more than two significant digits")
    return [COLORS[int(first[0])], COLORS[int(first[1])], COLORS[len(rest)]]


CASES = [
    (10, ["brown", "black", "black"]),
    (47, ["yellow", "violet", "black"]),
    (390, ["orange", "white", "brown"]),
    (4700, ["yellow", "violet", "red"]),
    (1_000_000, ["brown", "black", "green"]),
]
INVALID = [5, 4.5, 4750]


def check_bands():
    for ohms, expected in CASES:
        assert color_bands(ohms) == expected, ohms
    for ohms in INVALID:
        try:
            color_bands(ohms)
        except ValueError:
            continue
        raise AssertionError(f"no error for {ohms}")
    return len(CASES) + len(INVALID)


