import heapq


def grid_cost(grid):
    rows, cols = len(grid), len(grid[0])
    dist = {(0, 0): 0}
    heap = [(0, 0, 0)]
    while heap:
        d, r, c = heapq.heappop(heap)
        if (r, c) == (rows - 1, cols - 1):
            return d
        if d > dist[(r, c)]:
            continue                       # stale
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                nd = d + grid[nr][nc]
                if nd < dist.get((nr, nc), float("inf")):
                    dist[(nr, nc)] = nd
                    heapq.heappush(heap, (nd, nr, nc))
    return float("inf")


print(grid_cost([[1, 3, 1], [1, 5, 1], [4, 2, 1]]))   # 6
print(grid_cost([[5]]))
```

For the 3×3 grid the cheapest route is down, down, right, right: 1 + 4 + 2 + 1 = 8, or right, right, down, down: 3 + 1 + 1 + 1 = 6. The answer is 6. This version uses "skip if d is larger than the recorded distance" instead of a done set; both are correct.

